DO $do$
declare cfg jsonb := $j${"admin_decisions":{"p":"meetings:organize","o":"school_admin","rel":{"school":"school","meeting":"meeting_id","task":"task_id","responsible":"missing: no owner field in decisions (via linked task)"}},"admin_meetings":{"p":"meetings:organize","o":"school_admin","rel":{"school":"school","creator":"missing in API row (organizer)"}},"admin_requests":{"p":"admin_requests","o":"admin_workspace","rel":{"school":"school","responsible":"handler_user","creator":"excluded (submitted_by is personal)"},"x":[["open","قيد المعالجة","bool"],["days_waiting","أيام منذ التقديم","number"]]},"admissions":{"p":"admissions","o":"admissions","rel":{"school":"school","guardian":"guardian_name (contact excluded)","responsible":"missing in API row (assignee)"},"x":[["open","غير مكتمل/قيد المتابعة","bool"],["days_waiting","أيام منذ التقديم","number"]]},"buses":{"p":"maint_bus","o":"operations","rel":{"school":"school","riders":"sf_transport.bus_id"},"x":[["riders","عدد الطلاب المشتركين","number"],["fill_pct","نسبة الإشغال","percent"]]},"circulars":{"p":"circulars:publish","o":"school_admin","rel":{"school":"school","creator":"publisher_label (text)"}},"courses":{"p":"course_setup","o":"course_workspace","rel":{"school":"school","section":"section_id","subject":"subject_id","teacher":"via teacher_assignments"}},"custodies":{"p":"procurement","o":"finance","rel":{"school":"school","responsible":"holder_id"},"x":[["settle_overdue","تأخرت تسويتها","bool"]]},"discounts":{"p":"student_finance","o":"finance","rel":{"school":"org-level (central)"}},"duty_assignments":{"p":"duty_rosters","o":"admin_workspace","rel":{"school":"school","employee":"excluded (user_id personal)","roster":"roster_id"}},"duty_rosters":{"p":"duty_rosters","o":"admin_workspace","rel":{"school":"school"}},"event_applications":{"p":"evt_general","o":"school_admin","rel":{"school":"school","student":"student_id","event":"item_id","guardian":"via student_guardians (phase C)"}},"event_sessions":{"p":"evt_general","o":"school_admin","rel":{"school":"school","event":"item_id"}},"events":{"p":"evt_general","o":"school_admin","rel":{"school":"school","creator":"missing in API row (created_by)"},"x":[["applications","عدد الطلبات المقبولة مبدئيًا","number"],["accepted","عدد المقبولين","number"],["fill_pct","نسبة الإشغال","percent"],["reg_open","التسجيل مفتوح الآن","bool"]]},"gate_movements":{"p":"gate:operate","o":"school_admin","rel":{"school":"school","student":"student_id","guardian":"via student_guardians (phase C)"}},"gifted_programs":{"p":"gifted_care","o":"school_admin","rel":{"school":"school"}},"guidance_programs":{"p":"student_guidance","o":"school_admin","rel":{"school":"school"}},"health_calendar":{"p":"health","o":"school_admin","rel":{"school":"central calendar"}},"homework":{"p":"course_assignments","o":"course_workspace","rel":{"school":"school","section":"section_id","teacher":"via course teacher_assignments (phase C)"},"x":[["targets","عدد الطلاب المستهدفين","number"],["submitted","عدد التسليمات","number"],["graded","عدد المصحَّح","number"],["submit_pct","نسبة التسليم","percent"],["avg_score","متوسط الدرجة","number"]]},"hr_assets":{"p":"hr_assets","o":"hr","rel":{"school":"school","employee":"missing in API row"}},"hr_attendance":{"p":"hr_attendance","o":"hr","rel":{"school":"school","employee":"employee_id","manager":"via _au_manager (phase C)"}},"hr_employees":{"p":"hr_employees","o":"hr","rel":{"school":"school","employee":"id","manager":"via _au_manager (phase C)"}},"hr_leaves":{"p":"hr_leave","o":"hr","rel":{"school":"school","employee":"employee_id","manager":"via _au_manager (phase C)"},"x":[["pending","بانتظار الاعتماد","bool"]]},"hr_vacancies":{"p":"hr_recruit","o":"hr","rel":{"school":"school"}},"notices":{"p":"notices","o":"comm_hub","rel":{"school":"central","creator":"missing in API row"}},"procurement_expenses":{"p":"procurement","o":"finance","rel":{"school":"school"}},"procurement_requests":{"p":"procurement","o":"finance","rel":{"school":"school","creator":"missing in API row (requester)"},"x":[["open","قيد المعالجة","bool"],["days_waiting","أيام منذ التقديم","number"]]},"students":{"p":"people","o":"school_admin","rel":{"school":"school","student":"id","section":"section_id","guardian":"via student_guardians (phase C)"}},"substitutions":{"p":"school_schedule","o":"schedule_workspace","rel":{"school":"school","teacher":"substitute_teacher_id"}},"support_tickets":{"p":"support","o":"support","rel":{"school":"school","responsible":"missing in API row (assignee)"},"x":[["open","مفتوحة","bool"],["days_open","أيام منذ الفتح","number"],["awaiting_response","بانتظار أول رد","bool"],["response_late","تجاوزت موعد الرد","bool"]]},"teacher_assignments":{"p":"course_assignments","o":"course_workspace","rel":{"school":"school","teacher":"teacher_id","course":"course_id"},"x":[["live","الإسناد ساري اليوم","bool"]]},"timetables":{"p":"school_schedule","o":"schedule_workspace","rel":{"school":"school"}},"transport":{"p":"student_finance","o":"finance","rel":{"school":"school","student":"student_id","bus":"bus_id","guardian":"via student_guardians (phase C)"}}}$j$::jsonb;
 lk jsonb := $j${"school_id": "schools", "section_id": "sections", "grade_id": "grades", "stage_id": "stages", "year_id": "year_ids", "term_id": "terms", "subject_id": "subjects", "student_id": "students", "employee_id": "employees", "teacher_id": "teachers", "substitute_teacher_id": "teachers", "item_id": "evt_items", "bus_id": "buses", "form_id": "adm_forms", "post_id": "duty_posts", "type_id": "leave_types", "handler_user": "staff", "holder_id": "staff"}$j$::jsonb;
 fr text[] := array['agenda','body','description','link','note','notes','objectives','purpose','source_url']; dt text[] := array['ack_due','apply_by','available_from','birth_date','date','due_at','due_date','effective_from','end_date','ends','ends_at','ends_on','hire_date','inspection_date','invoice_date','license_expiry','next_service_date','reg_closes','reg_opens','settle_due','start_date','starts','starts_at','starts_on','week_start']; nu text[] := array['amount','capacity','days','duration_min','early_min','form_version','late_min','max_score','net','next_service_km','odometer','participants','rev','seats','seq','total','value','vat','version','weekly_periods','worked_min']; bo text[] := array['active','automatic','exempt','is_active','needs_consent','requires_ack']; stt text[] := array['audience','category','decision','domain','env','exec_status','gender','grade','kind','mode','nationality','op_status','priority','source','stage','status','term','topic','transport_type','value_type','year_key'];
 c jsonb; f jsonb; r text; vcode text; k text; t text; lkp text; excl jsonb; x jsonb;
begin
 for c in select e from jsonb_array_elements(_api_catalog()) e where cfg ? (e->>'key') loop
  r := c->>'key'; vcode := 'ds.api.'||r; excl := '[]'::jsonb;
  insert into au_events(code,label,recipients,section,area,source,source_kind,timing,sensitivity,dedupe,status,delivery)
   values (vcode,'مصدر بيانات: '||(c->>'label'),'{owner}',split_part(cfg->r->>'p',':',1),case when c->>'area'='central' then 'central' else 'school' end,
    '_api_rows_all:'||r,'scan','حسب جدولة القاعدة',case when c->>'sens' in ('شخصي','مالي','وظيفي') then 'sensitive' else 'normal' end,
    'rule+record+date (+تكرار)','wired','scheduled_scan') on conflict (code) do nothing;
  for f in select * from jsonb_array_elements(c->'fields') loop
   k := f->>'k';
   continue when k='id';
   if coalesce((f->>'s')::boolean,false) then excl := excl || jsonb_build_object('f',k,'why','حقل حساس'); continue; end if;
   if k = any(fr) then excl := excl || jsonb_build_object('f',k,'why','نص حر'); continue; end if;
   t := case when k='updated_at' or k like '%\_at' or k = any(dt) then 'date' when k = any(nu) then 'number' when k = any(bo) then 'bool'
             when k='external_id' then 'text' when lk ? k or k like '%\_id' then 'uuid' when k = any(stt) then 'status' else 'text' end;
   lkp := coalesce(lk->>k, case when t='status' then 'values' end);
   insert into au_variables(event_code,key,label,type,source,lookup,flags) values (vcode, case when k='school_id' then 'school' else k end, f->>'l', t, 'api:'||k, lkp,
     case when t in ('uuid','status','bool') and k not in ('task_id','slot_id','meeting_id') then '{group}'::text[] when t='text' then '{search}'::text[] else '{}'::text[] end)
     on conflict (event_code,key) do nothing;
   if t='date' and k<>'updated_at' then
     insert into au_variables(event_code,key,label,type,source,lookup,flags) values (vcode, k||'_days', 'الأيام حتى '||(f->>'l')||' (سالب = مضى)','number','days:'||k,null,'{}') on conflict do nothing;
   end if;
  end loop;
  if exists(select 1 from jsonb_array_elements(c->'fields') e where e->>'k'='school_id') then
    insert into au_variables(event_code,key,label,type,source,lookup,flags) values (vcode,'school_name','اسم المدرسة','text','calc:school_name',null,'{}') on conflict do nothing;
  end if;
  for x in select * from jsonb_array_elements(coalesce(cfg->r->'x','[]'::jsonb)) loop
    insert into au_variables(event_code,key,label,type,source,lookup,flags) values (vcode,x->>0,x->>1,x->>2,'calc:'||(x->>0),null,
      case when x->>2='bool' then '{group}'::text[] else '{}'::text[] end) on conflict do nothing;
  end loop;
  update au_sources set event_code=vcode, status='wired', perm_sections=array[cfg->r->>'p'], service='_api_rows_all:'||r,
    date_field=nullif(c->>'date',''), org_section=cfg->r->>'o', relations=cfg->r->'rel', excluded=excl,
    params=$p$[{"key":"repeat","type":"choice","label":"تكرار معالجة السجل نفسه","default":"once","options":[{"l":"مرة واحدة لكل سجل وتاريخ","v":"once"},{"l":"مرة يوميًا كحد أقصى","v":"daily"},{"l":"مرة أسبوعيًا كحد أقصى","v":"weekly"},{"l":"مرة شهريًا كحد أقصى","v":"monthly"}]}]$p$::jsonb,
    aggs='{count,count_distinct,sum,avg,min,max,pct}', reason=null, updated_at=now() where key='api:'||r;
 end loop;
end $do$;